with latest as (select * from (select *, row_number() over (partition by status order by opened_date desc nulls last, id) as row_num from accounts) t where row_num = 1) select case when balance >= 67000 then 'HIGH' else 'LOW' end as balance_tier, size(collect_set(status)) as num_status, round(avg(balance), 2) as avg_balance, max(balance) filter (where account_type = 'SAVINGS') as savings_max_balance from latest group by 1;
